import math
def ler_medida(texto):
    if not isinstance(texto,str):
        raise ValueError("Texto esperado")
    valor = float(texto)
    if not math.isfinite(valor):
        raise ValueError("A medida deve ser finita")
    return valor
assert ler_medida("2.5") == 2.5
for texto in ["dois", "nan", "inf", True, None]:
    try:
        ler_medida(texto)
    except ValueError:
        pass
    else:
        raise AssertionError(texto)
